&lt;table class=&quot;Bestiaire&quot;&gt;&lt;tr&gt;&lt;td&gt;
&lt;div class=&quot;BD&quot;&gt;
&lt;div class=&quot;BDtitre&quot;&gt;Jeune dragon du n&#233;ant&lt;div style=&quot;float:right;&quot;&gt;FP 9&lt;/div&gt;&lt;/div&gt;
&lt;div style=&quot;float:right&quot;&gt;
&lt;img title=&quot;Dragon&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Dragon.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Ciel&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Ciel.png&quot; style=&quot;opacity: 1&quot; /&gt;&lt;img title=&quot;Extraplanaire&quot; class=&quot;opachover&quot; src=&quot;/Wiki/public/Upload/Projets/Puces pour monstres/Extraplanaire.png&quot; style=&quot;opacity: 1&quot; /&gt;
&lt;/div&gt;
&lt;div class=&quot;BDtexte&quot;&gt;
&lt;i&gt;Source : Bestiaire 4 page 70&lt;/i&gt;
&lt;/div&gt;
&lt;b&gt;6 400 PX&lt;/b&gt;
&lt;ul&gt;&lt;li&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Type-Dragon.html&quot; title=&quot;Dragon&quot;&gt;Dragon&lt;/a&gt; de taille G, NM&lt;/li&gt;&lt;li&gt;&lt;b&gt;Init &lt;/b&gt;+2 ; Sens sens draconiques, vision dans les t&#233;n&#232;bres ; Perception +14&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;D&#233;fense&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;CA &lt;/b&gt;22, contact 11, pris au d&#233;pourvu 20 (Dex +2, naturelle +11, taille -1)&lt;/li&gt;&lt;li&gt;&lt;b&gt;pv &lt;/b&gt;95 (10d12+30)&lt;/li&gt;&lt;li&gt;&lt;b&gt;R&#233;f &lt;/b&gt;+9, &lt;b&gt;Vig &lt;/b&gt;+10, &lt;b&gt;Vol &lt;/b&gt;+10&lt;/li&gt;&lt;li&gt;&lt;b&gt;Immunit&#233;s &lt;/b&gt;confusion, effets d’ali&#233;nation mentale, froid, paralysie, sommeil&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Attaque&lt;/div&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;VD &lt;/b&gt;12 m, vol 60 m (bonne)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Corps &#224; corps&lt;/b&gt; morsure, +15 (2d6+7 plus oblit&#233;ration)&lt;ul&gt;&lt;li&gt;et 2 griffes, +14 (1d8+5)&lt;/li&gt;&lt;li&gt;et 2 ailes, +12 (1d6+2)&lt;/li&gt;&lt;li&gt;et coup de queue, +12 (1d8+7)&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Espace &lt;/b&gt;3 m ; &lt;b&gt;Allonge &lt;/b&gt;1,50 m (3 m avec la morsure)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Attaques sp&#233;ciales&lt;/b&gt; oblit&#233;ration (DD 18), souffle (c&#244;ne de 12 m, 6d8 froid, DD 18), souffle suffocant (DD 18)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Pouvoirs magiques&lt;/b&gt; (&lt;b&gt;NLS &lt;/b&gt;10 ; concentration +13)&lt;ul&gt;&lt;li&gt;&lt;i&gt;&#192; volont&#233;&lt;/i&gt; — rayon affaiblissant (DD 14)&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Sorts d’ensorceleur&lt;/b&gt; connus (&lt;b&gt;NLS &lt;/b&gt;1 ; concentration +4)&lt;ul&gt;&lt;li&gt;&lt;i&gt;1er (4/jour)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;Hypnose.html&quot; title=&quot;Hypnose&quot;&gt;hypnose&lt;/a&gt; (DD 15), &lt;a class=&quot;pagelink&quot; href=&quot;Armure-De-Mage.html&quot; title=&quot;Armure de mage&quot;&gt;armure de mage&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;i&gt;0 (&#224; volont&#233;)&lt;/i&gt; — &lt;a class=&quot;pagelink&quot; href=&quot;D&#233;tection-De-La-Magie.html&quot; title=&quot;D&#233;tection de la magie&quot;&gt;d&#233;tection de la magie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Lecture-De-La-Magie.html&quot; title=&quot;Lecture de la magie&quot;&gt;lecture de la magie&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Manipulation-&#192;-Distance.html&quot; title=&quot;Manipulation &#224; distance&quot;&gt;manipulation &#224; distance&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Message.html&quot; title=&quot;Message&quot;&gt;message&lt;/a&gt;&lt;br /&gt;&lt;div class=&quot;box&quot;&gt;Statistiques&lt;/div&gt;&lt;/li&gt;&lt;/ul&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;For &lt;/b&gt;21, &lt;b&gt;Dex &lt;/b&gt;14, &lt;b&gt;Con &lt;/b&gt;17, &lt;b&gt;Int &lt;/b&gt;16, &lt;b&gt;Sag &lt;/b&gt;13, &lt;b&gt;Cha &lt;/b&gt;16&lt;/li&gt;&lt;li&gt;&lt;b&gt;BBA &lt;/b&gt;+10 ; &lt;b&gt;BMO &lt;/b&gt;+16 ; &lt;b&gt;DMD &lt;/b&gt;28 (32 contre croc-en-jambe)&lt;/li&gt;&lt;li&gt;&lt;b&gt;Dons &lt;/b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Arme-De-Pr&#233;dilection.html&quot; title=&quot;Arme de pr&#233;dilection&quot;&gt;Arme de pr&#233;dilection&lt;/a&gt; (morsure), &lt;a class=&quot;pagelink&quot; href=&quot;Attaque-En-Vol.html&quot; title=&quot;Attaque en vol&quot;&gt;Attaque en vol&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Attaques-Multiples.html&quot; title=&quot;Attaques multiples&quot;&gt;Attaques multiples&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Virage-Sur-Laile.html&quot; title=&quot;Virage sur l&amp;#39;aile&quot;&gt;Virage sur l’aile&lt;/a&gt;, &lt;a class=&quot;pagelink&quot; href=&quot;Volont&#233;-De-Fer.html&quot; title=&quot;Volont&#233; de fer&quot;&gt;Volont&#233; de fer&lt;/a&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;Comp&#233;tences &lt;/b&gt;&lt;a class=&quot;pagelink&quot; href=&quot;Acrobaties.html&quot; title=&quot;Acrobaties&quot;&gt;Acrobaties&lt;/a&gt; +12, &lt;a class=&quot;pagelink&quot; href=&quot;Art-De-La-Magie.html&quot; title=&quot;Art de la magie&quot;&gt;Art de la magie&lt;/a&gt; +11, &lt;a class=&quot;pagelink&quot; href=&quot;Bluff.html&quot; title=&quot;Bluff&quot;&gt;Bluff&lt;/a&gt; +16, &lt;a class=&quot;pagelink&quot; href=&quot;Connaissances.html&quot; title=&quot;Connaissances&quot;&gt;Connaissances&lt;/a&gt; (myst&#232;res, plans) +13, &lt;a class=&quot;pagelink&quot; href=&quot;Diplomatie.html&quot; title=&quot;Diplomatie&quot;&gt;Diplomatie&lt;/a&gt; +13, &lt;a class=&quot;pagelink&quot; href=&quot;Discr&#233;tion.html&quot; title=&quot;Discr&#233;tion&quot;&gt;Discr&#233;tion&lt;/a&gt; +11, &lt;a class=&quot;pagelink&quot; href=&quot;Intimidation.html&quot; title=&quot;Intimidation&quot;&gt;Intimidation&lt;/a&gt; +16, &lt;a class=&quot;pagelink&quot; href=&quot;Perception.html&quot; title=&quot;Perception&quot;&gt;Perception&lt;/a&gt; +14, &lt;a class=&quot;pagelink&quot; href=&quot;Psychologie.html&quot; title=&quot;Psychologie&quot;&gt;Psychologie&lt;/a&gt; +14, &lt;a class=&quot;pagelink&quot; href=&quot;Survie.html&quot; title=&quot;Survie&quot;&gt;Survie&lt;/a&gt; +8, &lt;a class=&quot;pagelink&quot; href=&quot;Vol.html&quot; title=&quot;Vol&quot;&gt;Vol&lt;/a&gt; +19&lt;/li&gt;&lt;li&gt;&lt;b&gt;Langues &lt;/b&gt;abyssal, aklo, draconique, infernal&lt;/li&gt;&lt;li&gt;&lt;b&gt;Particularit&#233;s &lt;/b&gt;agile, ne respire pas, vol stellaire&lt;br /&gt;&lt;/div&gt;&lt;br /&gt;&lt;/td&gt;&lt;td&gt;&lt;div&gt;&lt;ul style=&quot;margin: 0 0 -10 0;margin-top: 6px;margin-bottom: 12px;&quot;&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Voir la description des &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Sid&#233;ral.html&quot; title=&quot;Les dragons sid&#233;raux&quot;&gt;dragons sid&#233;raux&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/li&gt;&lt;li&gt;&lt;b&gt;&lt;i&gt;Voir la description des &lt;a class=&quot;pagelink&quot; href=&quot;Dragon-Du-N&#233;ant.html&quot; title=&quot;Dragon sid&#233;ral du n&#233;ant&quot;&gt;dragons du n&#233;ant&lt;/a&gt;.&lt;/i&gt;&lt;/b&gt;&lt;/li&gt;&lt;/ul&gt;&lt;i&gt;Les cornes et les &#233;cailles d’&#233;b&#232;ne de ce dragon sont mouchet&#233;es d’une substance luisant d’une &#233;trange lumi&#232;re verte. Un ciel nocturne semble se ref l&#233;ter dans les plis de ses ailes.&lt;/i&gt;&lt;br /&gt;&lt;/div&gt;&lt;/td&gt;&lt;/tr&gt;&lt;/table&gt;&lt;br /&gt;&lt;/li&gt;&lt;/ul&gt;
